#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 512
#define MAX_PATH_LEN 256
#define DEFAULT_SECRET_KEY "supersecretkey_production_2024_xK9mP2"
#define HMAC_LEN 32

typedef struct {
    char username[64];
    char role[32];
    uint64_t expires;
    uint8_t signature[HMAC_LEN];
    size_t sig_len;
} auth_token_t;

typedef struct {
    char base_dir[MAX_PATH_LEN];
    int require_auth;
    int debug_mode;
} server_config_t;

/*
 * Load the secret key from the environment instead of hardcoding it.
 * In production this MUST come from a secure secret store / env variable
 * (e.g. AUTH_SECRET_KEY) and never be committed to source control.
 */
static const char *get_secret_key(void) {
    const char *k = getenv("AUTH_SECRET_KEY");
    if (k != NULL && k[0] != '\0') {
        return k;
    }
    /* Fallback for local/demo use only. */
    return DEFAULT_SECRET_KEY;
}

/*
 * Keyed hash used for token authentication.
 *
 * NOTE: This remains a simplified stand-in. For real deployments this MUST
 * be replaced with a standard, well-reviewed MAC such as HMAC-SHA256
 * (e.g. via OpenSSL's HMAC() / EVP_MAC APIs). The custom mixing below is
 * strengthened relative to the original but is still NOT a cryptographically
 * secure MAC and should not be relied upon in production.
 */
static void compute_hmac(const void *data, size_t data_len,
                         const char *key, uint8_t *out, size_t *out_len) {
    uint8_t state[HMAC_LEN];
    size_t key_len = strlen(key);
    if (key_len == 0) key_len = 1; /* avoid modulo-by-zero */

    /* Initialize state from key material. */
    for (size_t i = 0; i < HMAC_LEN; i++) {
        state[i] = (uint8_t)(key[i % key_len] ^ 0x36 ^ (uint8_t)i);
    }

    const uint8_t *bytes = (const uint8_t *)data;
    for (size_t i = 0; i < data_len; i++) {
        state[i % HMAC_LEN] ^= bytes[i];
        /* Diffuse each byte across the state to reduce trivial forgeability. */
        state[(i + 7) % HMAC_LEN] = (uint8_t)((state[(i + 7) % HMAC_LEN] + bytes[i] * 131u + 17u) & 0xFF);
    }

    /* Several finalization passes for better diffusion. */
    for (int pass = 0; pass < 4; pass++) {
        for (size_t i = 0; i < HMAC_LEN; i++) {
            state[i] = (uint8_t)((state[i] * 31u + state[(i + 1) % HMAC_LEN] + (uint8_t)key[i % key_len]) & 0xFF);
        }
    }

    memcpy(out, state, HMAC_LEN);
    *out_len = HMAC_LEN;
}

/* Sanitize path to prevent directory traversal */
static int sanitize_path(const char *input, char *output, size_t output_size) {
    if (!input || !output || output_size == 0) return -1;

    /* Reject any path with .. */
    if (strstr(input, "..") != NULL) return -1;

    /* Reject absolute paths */
    if (input[0] == '/') return -1;

    /* Reject backslashes */
    if (strchr(input, '\\') != NULL) return -1;

    /* Reject null bytes in the middle */
    size_t input_len = strlen(input);
    if (input_len == 0 || input_len >= output_size) return -1;

    /* Only allow alphanumeric, dots, hyphens, underscores, forward slashes */
    for (size_t i = 0; i < input_len; i++) {
        char c = input[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '.' || c == '-' ||
              c == '_' || c == '/')) {
            return -1;
        }
    }

    strncpy(output, input, output_size - 1);
    output[output_size - 1] = '\0';
    return 0;
}

/* Constant-time memory comparison */
static int secure_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/* Verify token signature */
static int verify_signature(const auth_token_t *token) {
    uint8_t expected[HMAC_LEN];
    size_t expected_len;

    /* Compute HMAC over username + role + expires */
    uint8_t msg_buf[128];
    size_t msg_len = 0;

    size_t ulen = strlen(token->username);
    size_t rlen = strlen(token->role);

    if (ulen + rlen + sizeof(uint64_t) > sizeof(msg_buf)) return 0;

    memcpy(msg_buf + msg_len, token->username, ulen);
    msg_len += ulen;
    memcpy(msg_buf + msg_len, token->role, rlen);
    msg_len += rlen;
    memcpy(msg_buf + msg_len, &token->expires, sizeof(uint64_t));
    msg_len += sizeof(uint64_t);

    compute_hmac(msg_buf, msg_len, get_secret_key(), expected, &expected_len);

    /* Signature must be exactly HMAC_LEN - reject truncated signatures */
    if (token->sig_len != HMAC_LEN) return 0;

    /* Constant-time comparison of full HMAC_LEN bytes */
    if (secure_compare(token->signature, expected, HMAC_LEN)) {
        return 1;
    }
    return 0;
}

/* Check if token is expired */
static int check_expiry(const auth_token_t *token) {
    time_t now = time(NULL);
    if ((uint64_t)now > token->expires) return 0;
    return 1;
}

/* Parse a token from wire format */
static int parse_token(const uint8_t *data, size_t data_len, auth_token_t *token) {
    if (!data || !token) return -1;
    if (data_len < 64 + 32 + 8 + 1 + HMAC_LEN) return -1; /* minimum: must include full sig */

    memset(token, 0, sizeof(auth_token_t));

    size_t offset = 0;

    /* Username: 64 bytes, null-padded */
    memcpy(token->username, data + offset, 64);
    token->username[63] = '\0';
    offset += 64;

    /* Role: 32 bytes, null-padded */
    memcpy(token->role, data + offset, 32);
    token->role[31] = '\0';
    offset += 32;

    /* Expires: 8 bytes LE */
    memcpy(&token->expires, data + offset, 8);
    offset += 8;

    /* Signature length: 1 byte */
    token->sig_len = data[offset];
    offset += 1;

    /* Signature must be exactly HMAC_LEN */
    if (token->sig_len != HMAC_LEN) return -1;
    if (offset + token->sig_len > data_len) return -1;
    memcpy(token->signature, data + offset, token->sig_len);

    return 0;
}

/* Authorize a file access request */
static int authorize_access(const server_config_t *config,
                           const uint8_t *token_data, size_t token_len,
                           const char *requested_path,
                           char *resolved_path, size_t resolved_size) {
    if (!config->require_auth) {
        /* No auth required - just sanitize path */
        return sanitize_path(requested_path, resolved_path, resolved_size);
    }

    auth_token_t token;
    if (parse_token(token_data, token_len, &token) != 0) {
        return -1;
    }

    if (!verify_signature(&token)) {
        return -1;
    }

    if (!check_expiry(&token)) {
        return -1;
    }

    /* Token valid - sanitize and resolve path */
    if (sanitize_path(requested_path, resolved_path, resolved_size) != 0) {
        return -1;
    }

    /* Admin role can access anything, user role restricted to public/ */
    if (strcmp(token.role, "admin") != 0) {
        if (strncmp(resolved_path, "public/", 7) != 0) {
            return -1;
        }
    }

    return 0;
}

int main(void) {
    server_config_t config;
    memset(&config, 0, sizeof(config));
    strncpy(config.base_dir, "/var/www/data", MAX_PATH_LEN - 1);
    config.require_auth = 1;
    config.debug_mode = 0;

    /* Create a legitimate admin token */
    auth_token_t legit_token;
    memset(&legit_token, 0, sizeof(legit_token));
    strncpy(legit_token.username, "admin_user", 63);
    strncpy(legit_token.role, "admin", 31);
    legit_token.expires = (uint64_t)time(NULL) + 3600;

    /* Sign it properly */
    uint8_t msg_buf[128];
    size_t msg_len = 0;
    memcpy(msg_buf, legit_token.username, strlen(legit_token.username));
    msg_len += strlen(legit_token.username);
    memcpy(msg_buf + msg_len, legit_token.role, strlen(legit_token.role));
    msg_len += strlen(legit_token.role);
    memcpy(msg_buf + msg_len, &legit_token.expires, 8);
    msg_len += 8;
    compute_hmac(msg_buf, msg_len, get_secret_key(), legit_token.signature, &legit_token.sig_len);

    /* Serialize token */
    uint8_t wire_token[MAX_TOKEN_LEN];
    size_t wire_len = 0;
    memcpy(wire_token + wire_len, legit_token.username, 64); wire_len += 64;
    memcpy(wire_token + wire_len, legit_token.role, 32); wire_len += 32;
    memcpy(wire_token + wire_len, &legit_token.expires, 8); wire_len += 8;
    wire_token[wire_len] = (uint8_t)legit_token.sig_len; wire_len += 1;
    memcpy(wire_token + wire_len, legit_token.signature, legit_token.sig_len);
    wire_len += legit_token.sig_len;

    char resolved[MAX_PATH_LEN];

    /* Test 1: Valid admin accessing private file */
    int r1 = authorize_access(&config, wire_token, wire_len,
                             "private/secrets.txt", resolved, sizeof(resolved));
    printf("Test 1 (admin, private): %s\n", r1 == 0 ? "GRANTED" : "DENIED");

    /* Test 2: Path traversal attempt */
    int r2 = authorize_access(&config, wire_token, wire_len,
                             "../etc/passwd", resolved, sizeof(resolved));
    printf("Test 2 (traversal): %s\n", r2 == 0 ? "GRANTED" : "DENIED");

    /* Test 3: Forged token with truncated signature - should be rejected */
    auth_token_t forged;
    memset(&forged, 0, sizeof(forged));
    strncpy(forged.username, "attacker", 63);
    strncpy(forged.role, "admin", 31);
    forged.expires = (uint64_t)time(NULL) + 7200;
    forged.sig_len = 1; /* Truncated - will be rejected */
    forged.signature[0] = 0x42;

    uint8_t forged_wire[MAX_TOKEN_LEN];
    size_t forged_len = 0;
    memcpy(forged_wire + forged_len, forged.username, 64); forged_len += 64;
    memcpy(forged_wire + forged_len, forged.role, 32); forged_len += 32;
    memcpy(forged_wire + forged_len, &forged.expires, 8); forged_len += 8;
    forged_wire[forged_len] = (uint8_t)forged.sig_len; forged_len += 1;
    memcpy(forged_wire + forged_len, forged.signature, forged.sig_len);
    forged_len += forged.sig_len;

    int r3 = authorize_access(&config, forged_wire, forged_len,
                             "private/secrets.txt", resolved, sizeof(resolved));
    printf("Test 3 (forged truncated sig): %s\n", r3 == 0 ? "GRANTED" : "DENIED");

    return 0;
}
